"use client"

import { useState, useTransition } from "react"
import { toggleNotificationPreference } from "../actions/notifications"
import { revalidatePath } from "next/cache"

export function NotificationToggle({ initialPreference }: { initialPreference: boolean }) {
  const [preference, setPreference] = useState(initialPreference)
  const [isPending, startTransition] = useTransition()

  const handleToggle = async () => {
    startTransition(async () => {
      const newPreference = await toggleNotificationPreference(preference)
      setPreference(newPreference)
      // Revalidate the current path to refresh server components
      revalidatePath("/")
    })
  }

  return (
    <div className="flex items-center gap-2">
      <button
        onClick={handleToggle}
        disabled={isPending}
        className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 disabled:bg-gray-400"
      >
        {isPending ? "Updating..." : preference ? "Turn Off" : "Turn On"}
      </button>
      <span>Notifications are {preference ? "ON" : "OFF"}</span>
    </div>
  )
}

